import React from 'react';
import { View } from 'react-native';

import { CardNumber } from '../../components/CardNumber';
import { styles } from './styles';

interface ListItemProps {
    data: {
        firstCard: number,
        id: string
    };
    list?: {
        [key: string]: [{
            id: number;
            name: string;
            phone: string;
            price: number;
            analyzed: number
        }]
    };
};

export function ListItem(listItemProps: ListItemProps) {
    return (
        <View style={styles.listItem}>
            <CardNumber {...{ listItemProps }} position={0} />
            <CardNumber {...{ listItemProps }} position={1} />
            <CardNumber {...{ listItemProps }} position={2} />
            <CardNumber {...{ listItemProps }} position={3} />
            <CardNumber {...{ listItemProps }} position={4} />
            <CardNumber {...{ listItemProps }} position={5} />
        </View>
    );
};
